\begin{tikzpicture}[line width=.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (O) at (0,0);\coordinate (P) at (2.3,.85);
\pgfmathsetmacro{\pxlocal}{2.3*cos(20)+.85*sin(20)}
\pgfmathsetmacro{\pylocal}{-2.3*sin(20)+.85*cos(20)}
\pgfmathsetmacro{\phase}{atan2(\pylocal/.85,\pxlocal/.3)}
\pgfmathsetmacro{\offset}{acos(1/sqrt((\pxlocal/.3)^2+(\pylocal/.85)^2))}
\begin{scope}[rotate=20]
\coordinate (T) at (0,.85);\coordinate (B) at (0,-.85);
\coordinate (TU) at ({.3*cos(\phase+\offset)},{.85*sin(\phase+\offset)});
\coordinate (TL) at ({.3*cos(\phase-\offset)},{.85*sin(\phase-\offset)});
\draw (0,0) ellipse [x radius=.3,y radius=.85];
\end{scope}
\draw (TU)--(P)--(TL);
\draw[line width=.4pt] (T)--(B);\fill (O) circle[radius=1.3pt];
\path (TU)--(P) node[midway,above] {$12\,\mathrm{cm}$};\path (T)--(B) node[midway,right] {$8\,\mathrm{cm}$};
\end{tikzpicture}

